import React, { useState, useRef } from 'react';
import { attendanceAPI } from './api_service';

const CameraRecognition = ({ addNotification }) => {
  const videoRef = useRef(null);
  const streamRef = useRef(null);

  const [cameraOn, setCameraOn] = useState(false);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [capturedImage, setCapturedImage] = useState(null);
  const [referenceImage, setReferenceImage] = useState(null);
  const [error, setError] = useState(null);

  // ▶️ Démarrer caméra
  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true });
      streamRef.current = stream;
      videoRef.current.srcObject = stream;
      setCameraOn(true);
    } catch (err) {
      setError("Impossible d'accéder à la caméra");
    }
  };

  // 🛑 Stop caméra
  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }
    setCameraOn(false);
  };

  // 📸 Capture + détection pendant 10s
  const handleDetect = async () => {
    if (!videoRef.current) return;

    setLoading(true);
    setError(null);
    setResult(null);

    const startTime = Date.now();
    let detected = false;

    while (Date.now() - startTime < 10000 && !detected) {
      try {
        const canvas = document.createElement('canvas');
        canvas.width = videoRef.current.videoWidth;
        canvas.height = videoRef.current.videoHeight;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(videoRef.current, 0, 0);

        const imageBase64 = canvas.toDataURL('image/jpeg');
        setCapturedImage(imageBase64);

        const response = await attendanceAPI.recognize(imageBase64);
        const data = response?.data;

        if (data.success && data.student) {
          detected = true;

          setResult({
            name: data.student,
            confidence: (data.confidence * 100).toFixed(1)
          });

          // image référence depuis backend (si dispo)
          if (data.reference_image) {
            setReferenceImage(data.reference_image);
          }

          addNotification(`✅ ${data.student} détecté`, 'success');
        }

      } catch (err) {
        console.warn(err);
      }
    }

    if (!detected) {
      setError("Aucun visage reconnu en 10 secondes");
    }

    setLoading(false);
  };

  return (
    <div style={styles.container}>
      <h1>Reconnaissance Faciale</h1>

      {!cameraOn ? (
        <button style={styles.btn} onClick={startCamera}>
          🎥 Démarrer Caméra
        </button>
      ) : (
        <>
          <video ref={videoRef} autoPlay style={styles.video} />

          <div style={styles.actions}>
            <button style={styles.btn} onClick={handleDetect} disabled={loading}>
              {loading ? 'Analyse (10s)...' : '🔍 Lancer Détection'}
            </button>

            <button style={{ ...styles.btn, background: '#EF4444' }} onClick={stopCamera}>
              🛑 Stop
            </button>
          </div>
        </>
      )}

      {error && <p style={styles.error}>{error}</p>}

      {/* 🖼️ Affichage côte à côte */}
      {(capturedImage || referenceImage) && (
        <div style={styles.imagesRow}>
          <div>
            <h4>📸 Capture</h4>
            {capturedImage && <img src={capturedImage} style={styles.image} />}
          </div>

          <div>
            <h4>🧑 Référence</h4>
            {referenceImage && <img src={referenceImage} style={styles.image} />}
          </div>
        </div>
      )}

      {result && (
        <div style={styles.result}>
          <h3>✅ {result.name}</h3>
          <p>Confiance: {result.confidence}%</p>
        </div>
      )}
    </div>
  );
};

const styles = {
  container: {
    padding: 20,
    textAlign: 'center'
  },
  video: {
    width: '100%',
    maxWidth: 500,
    borderRadius: 10,
    marginBottom: 20
  },
  actions: {
    display: 'flex',
    gap: 10,
    justifyContent: 'center'
  },
  btn: {
    padding: 12,
    border: 'none',
    borderRadius: 8,
    background: '#4F46E5',
    color: 'white',
    cursor: 'pointer'
  },
  error: {
    color: 'red'
  },
  imagesRow: {
    display: 'flex',
    justifyContent: 'center',
    gap: 20,
    marginTop: 20
  },
  image: {
    width: 200,
    borderRadius: 10,
    border: '2px solid #ddd'
  },
  result: {
    marginTop: 20,
    padding: 10,
    background: '#ECFDF5',
    borderRadius: 8
  }
};

export default CameraRecognition;
